/**
 * Markdown renderer for the public backtest leaderboard.
 *
 * Every number in the output traces to a cell of `reports/backtest-results.csv`;
 * nothing is hand-entered. The doc is bilingual (Vietnamese + English) and is
 * regenerated by `scripts/generate-leaderboard.mjs` — never edit it by hand.
 */

import type { LeaderboardCsvRow } from './leaderboard-csv-source.ts';
import {
  INFINITE_PF_LABEL,
  INSUFFICIENT_LABEL,
  MIN_SAMPLE_TRADES,
  NO_TRADES_LABEL,
  SMALL_SAMPLE_WARNING_LABEL,
  STATISTICALLY_SIGNIFICANT_TRADES,
  fixed,
  type RankedRow,
} from './leaderboard-cell-formatters.ts';
import { renderInsufficientTable, renderRankedTable } from './leaderboard-table-renderer.ts';

export {
  INFINITE_PF_LABEL,
  INSUFFICIENT_LABEL,
  MIN_SAMPLE_TRADES,
  NO_TRADES_LABEL,
  SMALL_SAMPLE_WARNING_LABEL,
  STATISTICALLY_SIGNIFICANT_TRADES,
  type RankedRow,
};

export interface LeaderboardStats {
  totalStrategies: number;
  withTrades: number;
  statisticallySignificantCount: number;
  smallSampleCount: number;
  withoutTrades: number;
  totalTrades: number;
  totalPnl: number;
  negativeSharpeCount: number;
  infiniteProfitFactorCount: number;
}

/**
 * Split ranked strategies from the ones that have no sample.
 * Rank is assigned only to rows with at least one trade, ordered by Sharpe.
 */
export function partitionRows(rows: LeaderboardCsvRow[]): {
  ranked: RankedRow[];
  insufficient: LeaderboardCsvRow[];
} {
  const measured = rows.filter((row) => row.total_trades >= MIN_SAMPLE_TRADES);
  const insufficient = rows.filter((row) => row.total_trades < MIN_SAMPLE_TRADES);

  const ordered = [...measured].sort(
    (a, b) => b.sharpe_ratio - a.sharpe_ratio || a.strategy.localeCompare(b.strategy),
  );
  const ranked = ordered.map((row, index) => ({ ...row, rank: index + 1 }));

  return { ranked, insufficient };
}

/** Totals computed strictly from the CSV rows. */
export function summarize(rows: LeaderboardCsvRow[]): LeaderboardStats {
  const withTrades = rows.filter((row) => row.total_trades >= MIN_SAMPLE_TRADES);
  const statisticallySignificant = withTrades.filter(
    (row) => row.total_trades >= STATISTICALLY_SIGNIFICANT_TRADES,
  );

  return {
    totalStrategies: rows.length,
    withTrades: withTrades.length,
    statisticallySignificantCount: statisticallySignificant.length,
    smallSampleCount: withTrades.length - statisticallySignificant.length,
    withoutTrades: rows.length - withTrades.length,
    totalTrades: withTrades.reduce((sum, row) => sum + row.total_trades, 0),
    totalPnl: rows.reduce((sum, row) => sum + row.total_pnl_usd, 0),
    negativeSharpeCount: withTrades.filter((row) => row.sharpe_ratio < 0).length,
    infiniteProfitFactorCount: withTrades.filter((row) => row.profit_factor === Infinity).length,
  };
}

/**
 * Render the full bilingual document.
 *
 * Header sections (platform, walk-forward, Monte Carlo) are only present when the
 * CSV supports them; unsourced methodology claims are omitted by design.
 */
export function renderLeaderboardDoc(rows: LeaderboardCsvRow[]): string {
  const { ranked, insufficient } = partitionRows(rows);
  const stats = summarize(rows);

  const rankedTable = renderRankedTable(ranked);
  const insufficientTable = renderInsufficientTable(insufficient);

  return `# Quantitative Backtest & Strategy Leaderboard / Bảng Xếp Hạng Chiến Lược

> **Tài liệu được sinh — đừng sửa tay / This file is generated — do not edit by hand.**
> Source / Nguồn: \`reports/backtest-results.csv\` (read through \`src/platform/api/routes/leaderboard-builder.ts\`,
> the same parser that serves \`GET /api/v1/leaderboard\`).
> Regenerate / Tạo lại: \`npm run generate:leaderboard\`
> Drift guard / Kiểm tra lệch: \`npm run check:leaderboard\`

---

## 1. What this table reports / Bảng này nói gì

Mỗi số dưới đây được lấy trực tiếp từ một dòng của \`reports/backtest-results.csv\` — không có số
nào được nhập tay. Chỉ những chiến lược có ít nhất ${MIN_SAMPLE_TRADES} lệnh mới được xếp hạng; các chiến
lược có 0 lệnh được liệt kê riêng và được đánh dấu "${INSUFFICIENT_LABEL}".

Every figure below comes straight from a row of \`reports/backtest-results.csv\` — none are typed in by
hand. Only strategies with at least ${MIN_SAMPLE_TRADES} trade are ranked; strategies with zero trades are
listed separately and marked "${INSUFFICIENT_LABEL}".

### Sample size / Cỡ mẫu

| Metric / Chỉ số | Value / Giá trị |
|:---|:---:|
| Strategies in CSV / Số chiến lược trong CSV | ${stats.totalStrategies} |
| Ranked (have trades) / Có xếp hạng (có lệnh) | ${stats.withTrades} |
| Statistically significant (≥ ${STATISTICALLY_SIGNIFICANT_TRADES} trades) / Đủ mẫu thống kê (≥ ${STATISTICALLY_SIGNIFICANT_TRADES} lệnh) | ${stats.statisticallySignificantCount} |
| Small sample (< ${STATISTICALLY_SIGNIFICANT_TRADES} trades — \`${SMALL_SAMPLE_WARNING_LABEL}\`) / Cỡ mẫu nhỏ (< ${STATISTICALLY_SIGNIFICANT_TRADES} lệnh) | ${stats.smallSampleCount} |
| Insufficient sample (0 trades — \`${NO_TRADES_LABEL}\`) / Không đủ dữ liệu (0 lệnh) | ${stats.withoutTrades} |
| Total trades backtested / Tổng số lệnh đã kiểm thử | ${stats.totalTrades} |
| Net P&L across all rows / Lãi lỗ ròng toàn bộ dòng | ${fixed(stats.totalPnl, 2)} USD |
| Ranked rows with negative Sharpe / Dòng có Sharpe âm | ${stats.negativeSharpeCount} |
| Ranked rows with infinite profit factor / Dòng có profit factor vô hạn | ${stats.infiniteProfitFactorCount} |

---

## 2. Ranked strategies / Chiến lược được xếp hạng

Xếp theo Sharpe giảm dần. Cỡ mẫu (\`total_trades\`) nằm ngay trong bảng — Sharpe cao trên vài lệnh
không phải là bằng chứng chất lượng. \`${INFINITE_PF_LABEL}\` có nghĩa là chiến lược không có lệnh thua
nào trong mẫu rất nhỏ: con số này không thể so sánh với profit factor hữu hạn.

Ordered by Sharpe, descending. The sample size (\`total_trades\`) is in the table — a high Sharpe over a
handful of trades is not evidence of quality. \`${INFINITE_PF_LABEL}\` means the strategy had no losing
trade in a very small sample; that number is not comparable to a finite one.

${rankedTable}

---

## 3. Insufficient sample / Không đủ dữ liệu

Các chiến lược sau có \`total_trades = 0\` trong CSV. Chúng **không** được gán Sharpe và **không** được
xếp hạng — cột trạng thái trong CSV của chúng không phải là hiệu năng.

The strategies below have \`total_trades = 0\` in the CSV. They are given **no** Sharpe value and **no**
rank — their response status is not performance.

${insufficientTable}

---

## 4. How these numbers are produced / Các con số được tạo ra như thế nào

1. **Single parser / Một trình đọc CSV:** bảng này được sinh bởi
   \`scripts/generate-leaderboard.mjs\`, đọc đúng \`reports/backtest-results.csv\` qua
   \`src/platform/api/routes/leaderboard-builder.ts\` — chính trình đọc phục vụ
   \`GET /api/v1/leaderboard\`. Không có trình đọc thứ hai.
2. **Drift guard / Chốt lệch tài liệu:** \`npm run check:leaderboard\` tạo lại tài liệu trong bộ nhớ và
   so khớp byte-by-byte với file đã commit. Nếu CSV đổi mà tài liệu không, CI fail.
3. **Generated artifact / Tài liệu được sinh ra:** đừng sửa tay file này. Sửa CSV (hoặc cách trình đọc
   diễn giải) rồi chạy lại generator.

Reproduce / Tái tạo:

\`\`\`bash
npm run generate:leaderboard   # regenerate docs/backtest-leaderboard.md from the CSV
npm run check:leaderboard      # fail if the committed doc has drifted
\`\`\`

---

## 5. Strategy marketplace / Chợ chiến lược

Nộp chiến lược qua \`src/platform/marketplace/\` — đó là nơi quản lý danh sách, đăng ký và đánh giá
chiến lược của nền tảng (không phải \`src/desk/strategies/marketplace.ts\`, một kho lưu trong bộ nhớ).

Submit strategies through \`src/platform/marketplace/\` — that is where the platform's listings,
subscriptions, and reviews live (not \`src/desk/strategies/marketplace.ts\`, an in-memory store).
`;
}
